//! Known answers for the key check of CC 2.6.1's verification order (rc20):
//! a row statement's signing key must be a key of its CWT `iss`, the key
//! `iss` names or one a rotation chain from it reaches (CC 2.6.1.7,
//! CC 2.4.1.1, CC 3.1.3); otherwise `kid_not_of_iss`.
//!
//! `tests/vectors/edition2/key_of_iss_v1.json` was generated by
//! `gen_key_of_iss.py` beside it, with its own CBOR encoder over dilithium-py
//! and pyca/cryptography, sharing no code with verify. Every case states its
//! directory (raw keys or key records) and its expected outcome.
#![cfg(feature = "pqc")]

use std::collections::BTreeMap;

use ciris_crypto::composite::{CompositePublicKey, CompositeSigningKey};
use ciris_verify_core::edition2::family::{
    verify_row_in_family, FamilyFault, FamilyVerdict, VendoredFamilyModel,
};
use ciris_verify_core::edition2::keys::KeyRecordDirectory;
use ciris_verify_core::edition2::{
    thumbprint, verify_row_statement, Digest32, Invalid, KeyDirectory, MissingKey, Verdict,
};
use serde_json::Value as J;

const FILE: &str = include_str!("vectors/edition2/key_of_iss_v1.json");

fn key(n: u8) -> CompositeSigningKey {
    CompositeSigningKey::from_seeds(&[n; 32], &[n.wrapping_add(100); 32])
}

fn hx(v: &J) -> Vec<u8> {
    hex::decode(v.as_str().unwrap()).unwrap()
}

fn directory(c: &J) -> Box<dyn KeyDirectory> {
    match c["directory"].as_str().unwrap() {
        "raw" => {
            let m: BTreeMap<Digest32, CompositePublicKey> = c["held_key_seeds"]
                .as_array()
                .unwrap()
                .iter()
                .map(|n| {
                    let k = key(u8::try_from(n.as_u64().unwrap()).unwrap());
                    (thumbprint(k.public_key()), k.public_key().clone())
                })
                .collect();
            Box::new(m)
        },
        "records" => {
            let mut d = KeyRecordDirectory::new();
            for r in c["records_hex"].as_array().unwrap() {
                d.insert(hx(r)).expect("a key record");
            }
            Box::new(d)
        },
        other => panic!("directory {other}"),
    }
}

fn label(v: &Verdict) -> String {
    match v {
        Verdict::Valid(_) => "valid".into(),
        Verdict::Waiting { missing } if missing.len() == 1 => match &missing[0] {
            MissingKey::Kid(k) => format!("waiting:kid:{}", hex::encode(k)),
            MissingKey::Record(r) => format!("waiting:record:{}", hex::encode(r)),
            other => format!("waiting:{other:?}"),
        },
        Verdict::Waiting { missing } => format!("waiting:{missing:?}"),
        Verdict::Invalid(i) => match i.token() {
            Some(t) => format!("invalid:{t}"),
            None => format!("invalid:{i:?}"),
        },
    }
}

#[test]
fn every_case_gives_its_outcome() {
    let f: J = serde_json::from_str(FILE).unwrap();
    let cases = f["cases"].as_array().unwrap();
    assert!(!cases.is_empty());
    for c in cases {
        let id = c["id"].as_str().unwrap();
        let bytes = hx(&c["statement_hex"]);
        let dir = directory(c);
        let got = match c["level"].as_str().unwrap() {
            "statement" => label(&verify_row_statement(&bytes, dir.as_ref())),
            "family" => {
                assert_eq!(c["model"].as_str(), Some("vendored"), "{id}");
                match verify_row_in_family(&bytes, dir.as_ref(), &VendoredFamilyModel) {
                    FamilyVerdict::Valid { role: None, .. } => "valid".into(),
                    FamilyVerdict::FamilyInvalid(FamilyFault::IssNotInRole) => {
                        "family_invalid:iss_not_in_role".into()
                    },
                    FamilyVerdict::Invalid(i) => label(&Verdict::Invalid(i)),
                    other => format!("{other:?}"),
                }
            },
            other => panic!("{id}: level {other}"),
        };
        assert_eq!(got, c["expect"].as_str().unwrap(), "{id}");
    }
}

/// The token is stable and named.
#[test]
fn kid_not_of_iss_token() {
    assert_eq!(Invalid::KidNotOfIss.token(), Some("kid_not_of_iss"));
}
